mapper.select:
SELECT child_id AS a, parent_id AS b FROM entity_type_parents p
                   JOIN entity_types t ON t.id = p.child_id
                  WHERE t.kb_id = #{kbId}

SELECT id FROM ontology_defects
  WHERE kb_id = #{kbId} AND kind = #{kind} AND subject = #{subject}
    AND other IS NOT DISTINCT FROM #{other}

WITH RECURSIVE sub AS (
     SELECT id FROM entity_types WHERE id = #{root} AND kb_id = #{kbId}
     UNION
     SELECT p.child_id FROM entity_type_parents p JOIN sub ON p.parent_id = sub.id
 )
SELECT id FROM sub

SELECT EXISTS (
     SELECT 1 FROM attribute_rules r
     JOIN attribute_rule_conditions c ON c.rule_id = r.id
      WHERE r.kb_id = #{kbId} AND r.id = #{ruleId}
        AND r.join_predicate_id IS NULL AND c.subject_side = 'y'
)
